// A row on the wire: the times serialised, since a Date does not survive JSON.stringify as one.
const summaryFrame = (summary: SessionSummary): SessionSummaryFrame => ({
  sessionId: summary.sessionId,
  createdAt: summary.createdAt.toISOString(),
  updatedAt: summary.updatedAt.toISOString(),
  entryCount: summary.entryCount,
});

// Asked on the unlocked path and answered when asked, never pushed: the list mutates nothing and is nobody's turn.
async function answerListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore,
  message: ListSessionsMessage
): Promise<void> {
  // The connection's user, never a field of the frame: the store is asked for one authenticated user's own list.
  const userId = (ws as ExtWebSocket).userId;
  try {
    const listed = sessionStore.listFor?.(userId, {limit: message.limit, before: message.before});
    // Awaited only when the store handed back a promise, so a synchronous answer is sent before the
    // pong the client sends behind this frame: that pong is the barrier its reader waits on.
    const summaries = listed instanceof Promise ? await listed : listed;
    sendJson(ws, {type: 'session_list', sessions: (summaries ?? []).map(summaryFrame)});
  } catch (reason) {
    // No list is not an answer: a client must not render a failed lookup as "no conversations".
    log.error('ws', 'conversation list failed', {
      sessionId: session.sessionId,
      userId,
      error: reason instanceof Error ? reason.message : String(reason),
    });
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
  }
}

